"""บทเรียนเสริมสำหรับหัวข้อ TPAT3 ที่มีชุดโจทย์อยู่แล้ว

ไฟล์นี้บันทึกเฉพาะบทเรียนและไม่สร้างหรือแก้โจทย์ของหัวข้อเดิม
"""
from author import *

SRC = ["หลักคณิตศาสตร์และฟิสิกส์ระดับมัธยมศึกษา", "แนวทักษะความถนัดเชิงตัวเลขและมิติสัมพันธ์"]


# ============================================================ numerical.number_grid
tid = "tpat3.aptitude.numerical.number_grid"
L = lesson(tid, "ตารางตัวเลขที่ต้องหาค่าที่หายไป",
    "อ่านตารางเป็นหลายลำดับที่ตัดกัน แล้วเลือกกฎง่ายที่สุดที่อธิบายข้อมูลได้ครบทุกแถวหรือทุกคอลัมน์",
    objectives=["ตรวจรูปแบบแนวนอน แนวตั้ง และแนวทแยงอย่างเป็นลำดับ", "แยกผลต่างคงที่ อัตราส่วนคงที่ และกฎผลรวมได้", "ใช้มากกว่าหนึ่งแถวตรวจยืนยันกฎก่อนตอบ"],
    minutes=30, prereq=["tgat2.numerical.series.constant_difference"],
    blocks=[
        hook("ตัวเลขช่องเดียวอาจเข้ากับกฎได้หลายแบบ สิ่งที่ทำให้คำตอบน่าเชื่อถือคือกฎเดียวกันต้องอธิบายช่องอื่นได้ด้วย"),
        concept("กฎที่ควรตรวจ",
            "เริ่มจากกฎง่ายก่อน ได้แก่ ผลต่างคงที่ เช่น +3 ทุกช่อง อัตราส่วนคงที่ เช่น ×2 ทุกช่อง ผลรวมแถว เช่น ช่องที่สามเท่ากับสองช่องแรกรวมกัน และกฎผสม เช่น คูณก่อนแล้วบวกค่าคงที่ จากนั้นจึงตรวจแนวตั้งและแนวทแยง"),
        technique("ตรวจจากง่ายไปยาก", "เมื่อยังไม่รู้ว่าตารางใช้กฎใด", "อย่าสร้างสูตรซับซ้อนจากแถวเดียว เพราะอาจบังเอิญพอดี",
            "1) กวาดดูขนาดและเครื่องหมาย 2) หาผลต่างในแต่ละแถว 3) หาอัตราส่วนเมื่อผลต่างไม่คงที่ 4) ตรวจผลรวม ผลคูณ หรือความสัมพันธ์ระหว่างช่อง 5) ทดลองกฎเดียวกันกับแถวหรือคอลัมน์อื่น 6) ใช้ทั้งแนวนอนและแนวตั้งยืนยันช่องที่หาย", tip="กฎที่สั้นและใช้ได้ครบหลายแถวมีน้ำหนักกว่ากฎยาวที่ใช้ได้เพียงแถวเดียว"),
        example("ตัวอย่างวิธีไล่หา", "แถวหนึ่งเป็น 4, 7, 10 และอีกแถวเป็น 9, 12, 15 ควรสังเกตอะไร",
            [("หาผลต่างแถวแรก", "+3 และ +3"), ("ตรวจแถวที่สอง", "+3 และ +3 เช่นกัน"), ("สรุปกฎชั่วคราว", "แต่ละแถวเพิ่มทีละ 3 แล้วตรวจคอลัมน์ประกอบ")], "ใช้กฎ +3 เป็นสมมติฐานแรก เพราะอธิบายได้ทั้งสองแถว"),
        pitfall("ยืนยันกฎจากข้อมูลน้อยเกินไป", "เห็นสองช่องแรกแล้วรีบเลือกกฎคูณสอง", "ตัวเลขสองค่ารองรับกฎได้ไม่จำกัด จึงต้องใช้ช่องที่สามหรืออีกแถวตรวจ", "ทดสอบกฎกับข้อมูลอย่างน้อยสองแนวหรือหลายแถวก่อนแทนช่องว่าง", "rule_from_two_values"),
        summary("เริ่มจากผลต่าง", "ต่อด้วยอัตราส่วน", "ตรวจผลรวมและกฎผสมเมื่อจำเป็น", "ยืนยันกฎด้วยแถว คอลัมน์ หรือแนวทแยงอื่น"),
        check("ถ้ากฎหนึ่งใช้ได้กับแถวแรก แต่ใช้ไม่ได้กับแถวอื่น ควรทำอย่างไร", ["ใช้กฎเดิมเพราะพบก่อน", "หากฎที่อธิบายข้อมูลได้ครบกว่า", "เฉลี่ยคำตอบทุกกฎ", "เลือกจำนวนที่ใหญ่ที่สุด"], 1, "กฎของตารางต้องสอดคล้องกับข้อมูลมากกว่าหนึ่งแถวหรือหนึ่งแนว"),
    ], patterns=["ผลต่างและอัตราส่วน", "ผลรวมแถว", "ตรวจข้ามแนว"], sources=SRC)
save(tid, "TPAT3", "mcq5", [], lesson=L)


# ============================================================ spatial.paper_fold_punch
tid = "tpat3.aptitude.spatial.paper_fold_punch"
L = lesson(tid, "พับกระดาษแล้วเจาะรู หาตำแหน่งรูเมื่อคลี่",
    "คลี่ย้อนลำดับการพับทีละรอย และสะท้อนตำแหน่งรูให้ห่างจากรอยพับเท่าเดิม",
    objectives=["อธิบายการคลี่เป็นการสะท้อนรอบรอยพับได้", "คลี่ย้อนจากพับครั้งสุดท้ายไปครั้งแรกได้", "ตรวจจำนวนและสมมาตรของรูหลังคลี่ได้"],
    minutes=30, prereq=["tpat3.foundation.read_mechanism_diagram"],
    blocks=[
        hook("รูหนึ่งรูบนกระดาษที่พับแล้วอาจกลายเป็นหลายรูเมื่อคลี่ แต่ตำแหน่งไม่ได้กระจายแบบสุ่ม ทุกตำแหน่งเป็นภาพสะท้อนจากรอยพับ"),
        concept("การพับคือการซ้อนชั้น การคลี่คือการสะท้อน",
            "เมื่อคลี่หนึ่งพับ จุดเดิมคงอยู่และเกิดจุดคู่สะท้อนอีกด้านของรอยพับ โดยอยู่ห่างรอยพับเท่ากัน ถ้าพับ $n$ ครั้งและรูไม่อยู่บนรอยพับหรือขอบที่ทำให้จุดซ้อนกัน จำนวนรูมากสุดคือ $2^n$ รู"),
        technique("คลี่ย้อนทีละพับ", "เมื่อมีรอยพับหลายทิศ", "อย่าคลี่ทุกพับพร้อมกัน เพราะจะสลับแกนหรือทิศได้ง่าย",
            "1) ระบุการพับครั้งสุดท้าย 2) สะท้อนรูข้ามรอยพับนั้นโดยรักษาระยะตั้งฉาก 3) รวมจุดเดิมกับจุดสะท้อน 4) ย้อนรอยพับก่อนหน้าและสะท้อนทุกจุดที่มี 5) ตรวจจำนวนรูและแนวสมมาตร", tip="ลำดับคลี่ต้องตรงข้ามกับลำดับพับ"),
        example("ตัวอย่างหลักการ", "กระดาษถูกพับครึ่งแนวตั้ง แล้วพับครึ่งแนวนอน ก่อนเจาะหนึ่งรูที่ไม่อยู่บนรอยพับ",
            [("คลี่แนวนอนก่อน", "หนึ่งรูสะท้อนเป็นสองรูที่อยู่เหนือ–ใต้ห่างรอยพับเท่ากัน"), ("คลี่แนวตั้งต่อ", "สะท้อนสองรูเดิมเป็นอีกสองรู"), ("ตรวจจำนวน", "ได้มากสุด 4 รูและสมมาตรทั้งสองแนว")], "คลี่ย้อนสองครั้งจึงได้มากสุด $2^2=4$ รู"),
        pitfall("นับเป็น $2^n$ โดยไม่ดูการซ้อน", "พับสามครั้งแล้วตอบแปดรูเสมอ", "ถ้ารูอยู่บนรอยพับ ภาพสะท้อนอาจทับจุดเดิม จำนวนรูจริงจึงน้อยกว่าค่าสูงสุด", "ใช้ $2^n$ เป็นเพดาน แล้วตรวจว่ามีรูบนรอยพับหรือจุดซ้อนกันหรือไม่", "always_max_holes"),
        summary("คลี่จากพับสุดท้ายย้อนกลับ", "แต่ละขั้นใช้การสะท้อน", "ระยะตั้งฉากจากรอยพับต้องเท่ากัน", "$2^n$ คือจำนวนสูงสุดเมื่อไม่มีจุดซ้อน"),
        check("พับสองครั้งและเจาะหนึ่งรูที่ไม่อยู่บนรอยพับ เมื่อคลี่หมดจะมีรูมากสุดกี่รู", ["2 รู", "3 รู", "4 รู", "8 รู"], 2, "$2^2=4$ รู เมื่อภาพสะท้อนไม่ซ้อนกัน"),
    ], patterns=["สะท้อนรอบรอยพับ", "คลี่ย้อนลำดับ", "ตรวจรูซ้อน"], sources=SRC)
save(tid, "TPAT3", "mcq5", [], lesson=L)


# ============================================================ mechanical.gear_trains
tid = "tpat3.aptitude.mechanical.gear_trains"
L = lesson(tid, "ระบบเฟือง ทิศการหมุนและอัตราทด",
    "แยกโจทย์เฟืองเป็นสองคำถาม: หมุนทิศใด และหมุนเร็วหรือให้แรงบิดเปลี่ยนเท่าไร",
    objectives=["หาทิศหมุนของเฟืองที่ขบต่อกันได้", "คำนวณอัตราทดจากจำนวนฟันได้", "อธิบายบทบาทของเฟืองกลางและสายพานไม่ไขว้ได้"],
    minutes=30, prereq=["tpat3.foundation.read_mechanism_diagram"],
    blocks=[
        hook("เฟืองกลางหลายตัวทำให้ภาพดูซับซ้อน แต่ถ้าถามอัตราเร็วของเฟืองต้นและปลาย จำนวนฟันของเฟืองกลางมักตัดกันหมด"),
        concept("กฎทิศและอัตราทด",
            "เฟืองภายนอกสองตัวที่ขบกันหมุนสวนทางกัน เฟืองที่ยึดบนเพลาเดียวกันหมุนทางเดียวกัน และล้อที่ต่อด้วยสายพานไม่ไขว้หมุนทางเดียวกัน สำหรับเฟืองคู่หนึ่ง อัตราทด $=N_{\\text{ตาม}}/N_{\\text{ขับ}}$ ดังนั้นเฟืองตามที่มีฟันมากกว่าจะหมุนช้าลงแต่ให้แรงบิดมากขึ้น"),
        technique("ไล่ทิศ แล้วค่อยหาอัตรา", "เมื่อระบบมีเฟืองหลายตัวหรือมีเพลาร่วม", "อย่านับจำนวนเฟืองอย่างเดียวโดยไม่ดูว่าเฟืองใดขบกันหรือยึดเพลาเดียวกัน",
            "1) ทำเครื่องหมายทิศเฟืองขับ 2) ทุกจุดขบให้กลับทิศ 3) เฟืองบนเพลาเดียวกันคงทิศ 4) สายพานไม่ไขว้คงทิศ 5) เมื่อถามอัตราเร็ว ใช้จำนวนฟันตัวขับและตัวตามตามแต่ละช่วง 6) ตรวจว่าเฟืองใหญ่ควรช้ากว่าเฟืองเล็ก", tip="แยกแผนที่ทิศออกจากการคำนวณอัตราทด"),
        example("ตัวอย่างเฟืองกลาง", "เฟือง A ขับเฟืองกลาง B และ B ขับเฟือง C",
            [("A ขบ B", "B หมุนสวนทางกับ A"), ("B ขบ C", "C หมุนสวนทางกับ B จึงทางเดียวกับ A"), ("ดูอัตรา", "อัตรา A ถึง C ขึ้นกับจำนวนฟัน A และ C ส่วนจำนวนฟัน B ตัดกัน")], "เฟืองกลางเปลี่ยนทิศที่ส่งต่อ แต่ไม่เปลี่ยนอัตราทดรวมระหว่างต้นกับปลาย"),
        pitfall("นำจำนวนฟันมาเทียบตรงทิศ", "เฟืองใหญ่กว่าจึงต้องหมุนทิศตรงข้ามเสมอ", "ขนาดกำหนดอัตราเร็ว ไม่ได้กำหนดทิศ ทิศขึ้นกับการขบ เพลาร่วม หรือชนิดสายพาน", "ไล่ชนิดการเชื่อมต่อเพื่อหาทิศ แล้วใช้จำนวนฟันหาอัตรา", "size_determines_direction"),
        summary("เฟืองขบกันหมุนสวนทาง", "เพลาเดียวกันและสายพานไม่ไขว้หมุนทางเดียวกัน", "อัตราทดเท่ากับฟันตัวตามหารฟันตัวขับ", "idler เปลี่ยนเส้นทางและทิศ แต่ไม่เปลี่ยนอัตราทดรวม"),
        check("เฟืองขับ 20 ฟันขับเฟืองตาม 60 ฟัน เฟืองตามหมุนอย่างไรเมื่อเทียบกับเฟืองขับ", ["เร็วขึ้น 3 เท่าและทางเดียวกัน", "เร็วขึ้น 3 เท่าและสวนทาง", "ช้าลง 3 เท่าและทางเดียวกัน", "ช้าลง 3 เท่าและสวนทาง"], 3, "เฟืองขบกันสวนทาง และเฟืองตามมีฟันสามเท่าจึงหมุนช้าลงสามเท่า"),
    ], patterns=["ทิศหมุน", "อัตราทด", "เฟืองกลางและเพลาร่วม"], sources=SRC)
save(tid, "TPAT3", "mcq5", [], lesson=L)
